using System;
using System.IO;
using System.Linq;
using UnityEngine;
public static class ProjectMapSceneTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception("PROJECT_MAP_SCENE: "+message);}
 static MapPoint P(float x,float z){return new MapPoint{x=x,z=z};}
 static MapData Fixture(){return new MapData{mapId="fixture",width=100,depth=100,roads=new[]{new MapRoad{id="r",name="road",width=4,lanes=1,points=new[]{P(5,5),P(95,5)}}},areas=new MapArea[0],stops=new MapStop[0],junctionRules=new HybridJunctionRule[0],hdEdges=new[]{new HdEdge{id="lane",fromNode="a",toNode="b",points=new[]{P(5,5),P(95,5)},next=new int[0]}},buildings=new[]{new MapBuilding{id="b",name="test",height=4,points=new[]{P(10,30),P(20,30),P(20,40),P(10,40)},triangles=new[]{0,1,2,0,2,3}}}};}
 static MapData Clone(MapData map){return JsonUtility.FromJson<MapData>(JsonUtility.ToJson(map));}
 static void Reject(Action action,string message){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}Check(rejected,message);}
 public static void Run(){
  var map=Fixture();string before=JsonUtility.ToJson(map);var scene=ProjectMapScene.Capture(map);Check(JsonUtility.ToJson(map)==before,"capture cannot mutate baseline");Check(scene.objects.Any(o=>o.kind=="sidewalk"),"procedural sidewalk polygons are captured");
  var cacheMap=Clone(map);cacheMap.editorBaseHash="unchanged-metadata";var cached=ProjectMapScene.Capture(cacheMap);cached.objects.First(o=>o.kind=="building").height=100;Check(ProjectMapScene.Capture(cacheMap).objects.First(o=>o.kind=="building").height==4,"capture cache returns independent editable copies");cacheMap.buildings[0].height=7;Check(ProjectMapScene.Capture(cacheMap).objects.First(o=>o.kind=="building").height==7,"capture cache hashes actual geometry despite stale metadata");
  var b=scene.objects.First(o=>o.kind=="building");foreach(var p in b.points)p.x+=5;b.height=8;var rendered=Clone(map);ProjectMapScene.Apply(rendered,scene);Check(rendered.buildings.Single().points[0].x==15&&rendered.buildings.Single().height==8,"edited footprint and height become actual building mesh input");Check(!SceneBuildingVisibility.Hidden(rendered,rendered.buildings[0].id),"authored building is never hidden by source overrides");
  int count=rendered.roads.Length;ProjectMapScene.Apply(rendered,scene);CorridorPolish.Apply(rendered);FuelStationLayout.Apply(rendered);RestaurantSiteLayout.Apply(rendered);Check(rendered.roads.Length==count,"regeneration does not append procedural surfaces");
  var doc=RoadMapDocument.Create(map);Check(doc.scene==null,"legacy document retains procedural behavior until scene captured");Check(doc.Copy().scene==null&&RoadMapDocument.Parse(doc.ToJson()).scene==null,"legacy null scene survives copy and JSON");Check(RoadMapDocument.Parse("{\"schema\":1,\"name\":\"\\\"scene\\\":{}\",\"lanes\":[],\"facilities\":[],\"signals\":[]}").scene==null,"nested text cannot invent a scene");Check(RoadMapDocument.Parse("{\"schema\":1,\"scene\":{\"objects\":[]}}").scene!=null,"explicit empty scene remains authored");doc.scene=scene;var copy=doc.Copy();Check(copy.scene.objects.Length==scene.objects.Length,"document JSON roundtrip keeps every scene object");var history=new RoadMapEditHistory(doc);history.Commit(doc);doc.scene.objects=doc.scene.objects.Where(o=>o.kind!="building").ToArray();ProjectMapScene.Apply(rendered,doc.scene);Check(rendered.buildings.Length==0,"delete removes collider footprint input");doc=history.Undo(doc);Check(doc.scene.objects.Any(o=>o.kind=="building"),"undo restores authored building");
  var concave=new[]{P(40,40),P(50,40),P(50,45),P(45,45),P(45,50),P(40,50)};var triangles=ProjectMapScene.Triangulate(concave);double area=0;for(int i=0;i<triangles.Length;i+=3){var a=concave[triangles[i]];var c=concave[triangles[i+1]];var d=concave[triangles[i+2]];area+=Math.Abs((c.x-a.x)*(d.z-a.z)-(c.z-a.z)*(d.x-a.x))*.5;}Check(Math.Abs(area-75)<.01,"concave triangulation covers exact polygon area");Check(ProjectMapScene.Triangulate(concave.Reverse().ToArray()).Length==12,"both windings supported");Check(ProjectMapScene.Triangulate(new[]{P(0,0),P(5,0),P(10,0),P(10,10),P(0,10)}).Length>=6,"collinear edge vertices supported");
  Reject(()=>ProjectMapScene.Triangulate(new[]{P(0,0),P(10,10),P(0,10),P(10,0)}),"bowtie rejected");Reject(()=>ProjectMapScene.Triangulate(new[]{P(0,0),P(10,0),P(10,0),P(0,10)}),"duplicate vertices rejected");Reject(()=>ProjectMapScene.Triangulate(new[]{P(0,0),P(10,0),P(5,0)}),"zero area rejected");
  var service=new ProjectMapObject{id="meal",kind="restaurant",name="moved meal",points=ProjectMapScene.Rectangle(new Vector3(65,0,40),Vector3.forward,10,12),laneId="lane",laneAt=50,serviceX=65,serviceZ=40,yaw=0};doc.scene.objects=doc.scene.objects.Concat(new[]{service,new ProjectMapObject{id="rest",kind="rest",name="rest",points=ProjectMapScene.Rectangle(new Vector3(80,0,40),Vector3.forward,10,12),laneId="lane",laneAt=70,serviceX=80,serviceZ=40,yaw=0},new ProjectMapObject{id="parking",kind="parking",name="parking",points=ProjectMapScene.Rectangle(new Vector3(80,0,60),Vector3.forward,10,12),laneId="lane",laneAt=70,serviceX=80,serviceZ=60,yaw=0},new ProjectMapObject{id="water",kind="water",name="water",points=ProjectMapScene.Rectangle(new Vector3(80,0,80),Vector3.forward,10,12)},new ProjectMapObject{id="land",kind="land",name="land",points=concave}}).ToArray();
  Check(!ProjectMapScene.Validate(map,doc).Any(i=>i.error),"valid edited scene accepted");var composed=RoadMapComposer.Compose(map,doc);Check(RestaurantSiteLayout.For(composed).parking==service.Position,"meal facility moves to authored bay");Check(FuelStationLayout.Rest(composed).pump==new Vector3(80,0,40),"rest facility moves to authored bay");Check(ProjectMapScene.CanUse(service,service.Position+Vector3.up*.65f,Vector3.forward,0),"meal action accepts physical bay stop");Check(!ProjectMapScene.CanUse(service,new Vector3(55,0,5),Vector3.forward,0)&&!ProjectMapScene.CanUse(service,service.Position,Vector3.back,0)&&!ProjectMapScene.CanUse(service,service.Position,Vector3.forward,1),"roadside/reversed/moving meals rejected");Check(ProjectMapScene.OnArea(composed,service.Position,false),"service court is drivable");Check(composed.hdEdges[0].points[0].x==map.hdEdges[0].points[0].x,"scene roads never silently edit lane graph");
  var elevated=doc.Copy();elevated.lanes[0].heights=new[]{.6f,.6f};elevated.scene.objects=elevated.scene.objects.Where(o=>o.kind!="road").ToArray();var elevatedMap=RoadMapComposer.Compose(map,elevated);Check(elevatedMap.roads.Length==1&&elevatedMap.roads[0].id=="editor:lane"&&elevatedMap.roads[0].points.All(p=>Math.Abs(p.elevation-.6f)<.001f),"authored scene preserves raised lane surface/collider without restoring deleted ground roads");
  var invalid=doc.Copy();invalid.scene.objects[0].id=invalid.scene.objects[1].id;Check(ProjectMapScene.Validate(map,invalid).Any(i=>i.error),"duplicate ID rejected");invalid=doc.Copy();invalid.scene.objects.First(o=>o.kind=="building").points[0].x=-1;Check(ProjectMapScene.Validate(map,invalid).Any(i=>i.error),"new outside boundary shape rejected");invalid=doc.Copy();invalid.scene.objects.First(o=>o.id=="meal").laneId="missing";Check(ProjectMapScene.Validate(map,invalid).Any(i=>i.error),"missing service access lane rejected");invalid=doc.Copy();invalid.scene.objects.First(o=>o.id=="meal").serviceX=2;Check(ProjectMapScene.Validate(map,invalid).Any(i=>i.error),"bay outside service polygon rejected");invalid=doc.Copy();invalid.scene.objects.First(o=>o.kind=="building").height=float.NaN;Check(ProjectMapScene.Validate(map,invalid).Any(i=>i.error),"nonfinite numeric input rejected");
  var overlapBase=Clone(map);ProjectMapScene.Apply(overlapBase,doc.scene);var overlapDoc=doc.Copy();overlapDoc.scene.objects=overlapDoc.scene.objects.Concat(new[]{new ProjectMapObject{id="new-blocker",kind="building",name="blocker",height=5,points=new[]{P(65.5f,39),P(66.5f,39),P(66.5f,41),P(65.5f,41)}}}).ToArray();Check(ProjectMapScene.Validate(overlapBase,overlapDoc).Any(i=>i.error&&i.id=="meal"),"new building colliding only with unchanged service vehicle side is rejected");overlapDoc.scene.objects.Last().kind="water";Check(ProjectMapScene.Validate(overlapBase,overlapDoc).Any(i=>i.error&&i.id=="meal"),"new water over unchanged service vehicle footprint is rejected");
  var disconnected=Fixture();disconnected.stops=new[]{new MapStop{name="origin",graphStop=true,laneEdge=0,laneAt=10,x=15,z=5,dx=1,dz=0,width=3}};disconnected.hdEdges=disconnected.hdEdges.Concat(new[]{new HdEdge{id="island",fromNode="c",toNode="d",points=new[]{P(40,80),P(70,80)},next=new int[0]}}).ToArray();var disconnectedDoc=RoadMapDocument.Create(disconnected);disconnectedDoc.scene=ProjectMapScene.Capture(disconnected);disconnectedDoc.scene.objects=disconnectedDoc.scene.objects.Concat(new[]{new ProjectMapObject{id="island-meal",kind="restaurant",name="unreachable",laneId="island",laneAt=10,serviceX=50,serviceZ=65,points=ProjectMapScene.Rectangle(new Vector3(50,0,65),Vector3.forward,8,10)}}).ToArray();Check(RoadMapValidator.Validate(disconnected,disconnectedDoc).Any(i=>i.error&&i.id=="island-meal"&&i.message.Contains("접근 불가")),"valid existing lane cannot hide an unreachable service");
  var clipped=Fixture();clipped.buildings[0].points[0].x=-3;var clippedDoc=RoadMapDocument.Create(clipped);clippedDoc.scene=ProjectMapScene.Capture(clipped);Check(!ProjectMapScene.Validate(clipped,clippedDoc).Any(i=>i.error),"unchanged imported clipped bounds grandfathered");
  var deleted=doc.Copy();deleted.scene.objects=deleted.scene.objects.Where(o=>!o.IsService).ToArray();var removed=RoadMapComposer.Compose(map,deleted);Check(RestaurantSiteLayout.For(removed)==null&&FuelStationLayout.Rest(removed)==null,"deleted service never recreated by procedural defaults");
  bool projectSource=ProjectMapBuild.HasSource;var real=projectSource?ProjectMapStore.Load(ProjectMapBuild.Root).baseline:JsonUtility.FromJson<MapData>(File.ReadAllText("Assets/Resources/eungye-hybrid-map.json"));real.mapId="eungye";if(!projectSource)ReviewedLaneLayout.Apply(real);var realDoc=RoadMapDocument.Create(real);realDoc.scene=ProjectMapScene.Capture(real);foreach(var walk in realDoc.scene.objects.Where(o=>o.id.StartsWith("sidewalk:reviewed:")))Check(ProjectMapScene.Triangulate(walk.points).Length>=3,"reviewed triangle soup becomes editable simple polygon: "+walk.id);var problems=ProjectMapScene.Validate(real,realDoc);Check(!problems.Any(i=>i.error),"actual Eungye capture validates: "+string.Join(" / ",problems.Take(4)));var actual=RoadMapComposer.Compose(real,realDoc);int actualCount=actual.roads.Length;FuelStationLayout.Apply(actual);RestaurantSiteLayout.Apply(actual);CorridorPolish.Apply(actual);Check(actual.roads.Length==actualCount&&FuelStationLayout.For(actual).Count==3,"Eungye regeneration retains geometry and three fuel stations");Check(realDoc.scene.objects.Any(o=>o.kind=="restaurant")&&realDoc.scene.objects.Any(o=>o.kind=="rest")&&realDoc.scene.objects.Any(o=>o.kind=="parking"),"all baseline services captured");
  var noParking=realDoc.Copy();foreach(var parking in noParking.scene.objects.Where(o=>o.kind=="parking"))parking.enabled=false;Check(ProjectMapScene.Validate(real,noParking).Any(i=>i.error&&i.message.Contains("주차장 1개")),"missing day start parking rejected");
  Debug.Log("PROJECT_MAP_SCENE_TEST_OK geometry,concave,roundtrip,undo,delete,services,validation,Eungye objects="+realDoc.scene.objects.Length);
 }
}
